	private static class CollationInfoHelper
	{
		public static readonly CollationInfo Ordinal;

		public static readonly CollationInfo OrdinalIgnoreCase;

		public static readonly CollationInfo Default;

		public static readonly Dictionary<int, StringComparer> CSComparers;

		public static readonly Dictionary<int, StringComparer> CIComparers;

		public static readonly DualTypeSortedListCollection<CollationInfo, ICollation> Collations;

		[DebuggerHidden]
		static CollationInfoHelper()
		{
			Ordinal = new CollationInfo("Ordinal", StringComparer.Ordinal, CompareOptions.Ordinal);
			OrdinalIgnoreCase = new CollationInfo("OrdinalIgnoreCase", StringComparer.OrdinalIgnoreCase, CompareOptions.OrdinalIgnoreCase);
			CSComparers = new Dictionary<int, StringComparer>(85);
			CIComparers = new Dictionary<int, StringComparer>(85);
			PopulateStringComparerLookups(CSComparers, CIComparers);
			Collations = new DualTypeSortedListCollection<CollationInfo, ICollation>(2400, OrdinalIgnoreCase);
			Collations.Add(new CultureAwareCollationInfo("SQL_Latin1_General_CP1_CI_AS", 1033, TryGetCultureInfo(1033), CompareOptions.IgnoreCase | CompareOptions.IgnoreKanaType | CompareOptions.IgnoreWidth));
			Collations.Add(new CultureAwareCollationInfo("SQL_Latin1_General_CP1_CI_AI", 1033, TryGetCultureInfo(1033), CompareOptions.IgnoreCase | CompareOptions.IgnoreNonSpace | CompareOptions.IgnoreKanaType | CompareOptions.IgnoreWidth));
			Collations.Add(new CultureAwareCollationInfo("SQL_Latin1_General_CP1_CS_AS", 1033, TryGetCultureInfo(1033), CompareOptions.IgnoreKanaType | CompareOptions.IgnoreWidth));
			Default = Collations["SQL_Latin1_General_CP1_CI_AS"];
		}
	}

	private sealed class CultureAwareCollationInfo : CollationInfo, IComparer<string>, IEqualityComparer<string>
	{
		private readonly StringComparer m_hashGenarator;

		public CultureAwareCollationInfo(string name, int lcid, CultureInfo cultureInfo, CompareOptions compareOptions)
			: base(name, lcid, cultureInfo, compareOptions)
		{
			bool flag = (compareOptions & CompareOptions.IgnoreCase) == CompareOptions.IgnoreCase;
			m_hashGenarator = (flag ? CollationInfoHelper.CIComparers[lcid] : CollationInfoHelper.CSComparers[lcid]);
		}

		public int Compare(string x, string y)
		{
			return m_compareInfo.Compare(x, y, m_compareOptions);
		}

		public bool Equals(string x, string y)
		{
			return Compare(x, y) == 0;
		}

		public int GetHashCode(string obj)
		{
			return m_hashGenarator.GetHashCode(obj);
		}

		private static CompareOptions GetCompareInfo(string collationName)
		{
			return CompareOptions.None;
		}
	}

	private const string DefaultCollationName = "SQL_Latin1_General_CP1_CI_AS";

	private static object syncObj = new object();

	private readonly string m_collationName;

	private readonly IComparer<string> m_comparer;

	private readonly IEqualityComparer<string> m_equalityComparer;

	private readonly CompareInfo m_compareInfo;

	private readonly CompareOptions m_compareOptions;

	private readonly int m_lcid;

	public static CollationInfo Default => CollationInfoHelper.Default;

	public static CollationInfo Ordinal => CollationInfoHelper.Ordinal;

	public static CollationInfo OrdinalIgnoreCase => CollationInfoHelper.OrdinalIgnoreCase;

	public static IMetadataCollection<ICollation> Collations => CollationInfoHelper.Collations;

	public int LCID => m_lcid;

	public IComparer<string> Comparer => m_comparer;

	public IEqualityComparer<string> EqualityComparer => m_equalityComparer;

	public string Name => m_collationName;

	public static CollationInfo GetCollationInfo(string collationName)
	{
		if (collationName == null)
		{
			throw new ArgumentNullException("collationName");
		}
		return GetCollationInfoInternal(collationName);
	}

	public static CollationInfo GetCollationInfo(ICollation collation)
	{
		if (collation == null)
		{
			throw new ArgumentNullException("collation");
		}
		return (collation as CollationInfo) ?? GetCollationInfo(collation.Name);
	}

	public static CollationInfo GetCollationInfo(int lcid, CompareOptions compareOptions)
	{
		lock (syncObj)
		{
			foreach (CollationInfo collation in CollationInfoHelper.Collations)
			{
				if (collation.LCID == lcid && collation.m_compareOptions == compareOptions)
				{
					return collation;
				}
			}
			foreach (CollationInfo item in GetCollationInfoCollection().OfType<CollationInfo>())
			{
				if (item.LCID == lcid && item.m_compareOptions == compareOptions)
				{
					CollationInfoHelper.Collations.Add(item);
					return item;
				}
			}
		}
		return null;
	}

	private CollationInfo(string name, StringComparer stringComparer, CompareOptions compareOptions)
	{
		m_collationName = name;
		m_comparer = stringComparer;
		m_equalityComparer = stringComparer;
		m_compareInfo = CultureInfo.InvariantCulture.CompareInfo;
		m_compareOptions = compareOptions;
		m_lcid = NetCoreHelpers.InvariantCultureLcid;
	}

	private CollationInfo(string name, int lcid, CultureInfo cultureInfo, CompareOptions compareOptions)
	{
		m_collationName = name;
		m_comparer = (IComparer<string>)this;
		m_equalityComparer = (IEqualityComparer<string>)this;
		m_compareInfo = cultureInfo.CompareInfo;
		m_compareOptions = compareOptions;
		m_lcid = lcid;
	}

	public bool IsPrefix(string source, string prefix)
	{
		return m_compareInfo.IsPrefix(source, prefix, m_compareOptions);
	}

	public override string ToString()
	{
		return m_collationName;
	}

	T IMetadataObject.Accept<T>(IMetadataObjectVisitor<T> visitor)
	{
		if (visitor == null)
		{
			throw new ArgumentNullException("visitor");
		}
		return visitor.Visit(this);
	}

	[DebuggerHidden]
	private static CultureInfo TryGetCultureInfo(int id)
	{
		try
		{
			return CultureInfo.GetCultureInfo(id);
		}
		catch (ArgumentException)
		{
			return CultureInfo.InvariantCulture;
		}
	}

	private static CollationInfo GetCollationInfoInternal(string collationName)
	{
		if (collationName == null)
		{
			throw new ArgumentNullException("collationName");
		}
		lock (syncObj)
		{
			if (CollationInfoHelper.Collations.Contains(collationName))
			{
				return CollationInfoHelper.Collations[collationName];
			}
			foreach (ICollation item in GetCollationInfoCollection())
			{
				if (string.Compare(collationName, item.Name, ignoreCase: true) == 0 && item is CollationInfo collationInfo)
				{
					CollationInfoHelper.Collations.Add(collationInfo);
					return collationInfo;
				}
			}
		}
		return null;
	}

